let wizardState=null;
function startWizard(i){wizardState={id:i,node:'scope',history:[],help:false,result:null};renderWizard();}
function wizardBack(){if(!wizardState.history.length){showGuide(wizardState.id);wizardState=null;return;}const last=wizardState.history.pop();wizardState.node=last.node;wizardState.help=false;wizardState.result=null;renderWizard();}
function answerWizard(answer){const w=wizardState,f=TROUBLESHOOT[w.id],n=f.nodes[w.node];if(answer==='unknown'){w.help=true;renderWizard();return;}w.history.push({node:w.node,q:n.q,answer:answer==='yes'?(n.yesLabel||'예'):(n.noLabel||'아니요')});const next=n[answer];w.help=false;if(f.nodes[next])w.node=next;else w.result=next;renderWizard();}
function renderWizard(){$('content').scrollIntoView?.({block:'start',behavior:'auto'});const w=wizardState,f=TROUBLESHOOT[w.id],n=f.nodes[w.node];renderNav();$('content').innerHTML=`<section class="wizard"><div class="section-heading"><h2>${f.name} · 질문형 점검</h2><button data-guide="${w.id}">전체 안내</button></div><p class="wizard-note">편람에 근거한 다음 점검 안내입니다. 현장 상태를 확인하며 진행하세요.</p><div class="wizard-trail">${w.history.length?w.history.map((h,j)=>`<span>${j+1}. ${esc(h.answer)}</span>`).join(''):'첫 질문'}</div>`+
(w.result?wizardResult(f,w):`<div class="question-card"><span class="eyebrow">${w.history.length+1}번째 확인</span><h3>${n.q}</h3><div class="answer-options"><button data-answer="yes">${n.yesLabel||'예'}</button><button data-answer="no">${n.noLabel||'아니요'}</button><button data-answer="unknown">확인하지 못함</button></div>${articleRefs(n.refs)}${w.help?`<div class="measurement-help" role="status"><h3>이렇게 확인하세요</h3><p>${n.method}</p><p class="article-note">확인 후 위에서 답변을 선택하세요. 지금 측정하기 어렵다면 확인할 항목을 먼저 정리할 수 있습니다.</p><button data-pending>확인할 항목 정리</button></div>`:''}</div>`)+`<div class="wizard-actions"><button data-wizard-back>${w.history.length?'이전 답변 수정':'점검 안내로 돌아가기'}</button><button data-wizard="${w.id}">처음부터</button></div><p class="guide-source">한국지역난방공사 · 지역난방 열사용시설 관리업무 편람 (2025.10). 밸브 분해·압력조정·혼수검사는 현장 작업절차와 제작사 기준에 따라 시행합니다.</p></section>`;}
function wizardResult(f,w){const pending=w.result==='pending',n=f.nodes[w.node];const r=pending?{title:'먼저 현재 상태를 확인하세요',why:'확인되지 않은 항목을 측정한 뒤 답변하면 점검 경로를 더 좁힐 수 있습니다.',items:[n.method],refs:n.refs}:f.results[w.result];return resultMeasurementLinks(w)+`<div class="wizard-result"><span class="eyebrow">${pending?'추가 확인 필요':'우선 점검 안내'}</span><h3>${r.title}</h3><p>${r.why}</p><h4>확인·측정할 항목</h4><ol>${r.items.map(t=>`<li>${t}</li>`).join('')}</ol>${articleRefs(r.refs)}${pending?'<button class="resume-button" data-resume>측정 후 현재 질문에 답하기</button>':''}</div><details class="answer-summary" open><summary>답변 기록 ${w.history.length}개</summary>${w.history.length?w.history.map(h=>`<div><strong>${esc(h.q)}</strong><span>${esc(h.answer)}</span></div>`).join(''):'<p>아직 확인된 답변이 없습니다.</p>'}${pending?`<div><strong>${n.q}</strong><span>확인하지 못함</span></div>`:''}</details>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-wizard'))startWizard(Number(b.dataset.wizard));else if(b.dataset.answer&&wizardState)answerWizard(b.dataset.answer);else if(b.hasAttribute('data-wizard-back')&&wizardState)wizardBack();else if(b.hasAttribute('data-pending')&&wizardState){wizardState.result='pending';renderWizard();}else if(b.hasAttribute('data-resume')&&wizardState){wizardState.result=null;wizardState.help=true;renderWizard();}});
