guideHome=function(){return '<div class="section-heading"><h2>어떤 증상이 있나요?</h2><span class="count">8개 질문형 점검</span></div><p class="home-note">증상을 선택하면 상태에 맞는 다음 점검과 관련 원문을 안내합니다.</p><div class="diagnosis-grid">'+GUIDES.map((g,i)=>`<div class="diagnosis-card"><button class="diagnosis-main" data-wizard="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><strong>${g.title}</strong><span>${g.sub}</span><b>질문형 점검 시작</b></button><button class="diagnosis-reference" data-guide="${i}">점검 안내 전체 보기</button></div>`).join('')+'</div><div class="home-reference"><strong>설비별 편람은 메뉴에서 선택하세요.</strong><p>차압유량조절밸브·열교환기·펌프 등 설비별 핵심 본문과 원문은 PC 왼쪽 메뉴, 모바일 상단 메뉴에서 열 수 있습니다.</p></div>';};
home=function(){renderNav();$('query').value='';$('content').innerHTML=guideHome();};

const MEASUREMENTS={"he": {"title": "열교환기 점검 위치", "note": "1차측 중온수와 2차측 난방·급탕수는 서로 섞이지 않고 전열판을 통해 열을 전달합니다.", "refs": [126, 128, 147], "points": [["1차측 공급·입구", 13, 26, "온도 T₁in · 압력 P₁in", "열교환기 1차측 입구의 설치된 온도·압력계를 확인합니다. 밸브나 배관 표기를 따라 입구를 식별하세요.", "1차측 출구값과 같은 시간에 기록해 입출구 압력차·온도차를 비교합니다.", [128, 147]], ["1차측 회수·출구", 87, 26, "온도 T₁out · 압력 P₁out", "열교환기 1차측 출구에서 지역난방 회수배관으로 연결되는 계측값을 확인합니다.", "1차측 압력손실 = P₁in − P₁out. 회수온도가 높게 유지되는지 정상운전 이력과 비교합니다.", [147, 157]], ["2차측 공급·출구", 13, 73, "온도 T₂out · 압력 P₂out", "세대로 보내는 난방·급탕 공급측 온도·압력을 확인합니다. 현장 펌프 설치위치에 따라 계측위치를 구분하세요.", "설정온도와 실제 공급온도를 비교합니다. 2차측 출구압력은 입구압력과 짝지어 비교합니다.", [128, 147]], ["2차측 회수·입구", 87, 73, "온도 T₂in · 압력 P₂in", "난방 회수 또는 급탕 입구 배관의 계측값을 확인합니다. 급탕은 시수·환탕·예열 구성에 따라 입구가 달라질 수 있습니다.", "2차측 압력손실 = P₂in − P₂out. 펌프를 사이에 둔 계기의 차이를 열교환기 손실로 해석하지 않습니다.", [127, 128, 147]], ["TCV·바이패스", 30, 26, "밸브 개도 · 실제 동작 · 바이패스 상태", "도면·배관 표기로 1차측 TCV와 바이패스를 확인합니다. 그림의 TCV 위치는 개념 예시입니다.", "지시 개도와 실제 동작을 비교합니다. 닫힘 지시에도 과열되면 밀림·바이패스·혼수 가능성을 검토합니다.", [186, 150]]], "compare": ["1차측 압력손실은 입구압력에서 출구압력을 뺍니다. 2차측도 해당 유체 입구 − 출구로 계산합니다.", "편람의 정상 압력손실 설명: 1차측 0.2 bar, 2차측 0.3 bar 이내. 현장 설계·운전유량·정상기록을 함께 비교합니다.", "2차측 공급온도가 낮고 1차측 회수온도가 높게 유지되며 압력손실이 증가하면 전열판 오염을 검토할 수 있습니다."], "pro": "혼수시험·분해·세척·누설시험은 제작사 또는 전문업체 작업입니다. 차단·냉각·무압 확인은 현장 작업절차에 따릅니다."}, "pump": {"title": "순환펌프 점검 위치", "note": "유체의 흐름을 따라 흡입·토출측을 구분합니다. 아래는 인라인펌프를 단순화한 계측 위치도입니다.", "refs": [210, 211, 220, 221], "points": [["흡입측", 16, 66, "흡입압력 · 유체온도", "펌프 흡입측에 설치된 계기와 배관의 유체흐름 방향을 확인합니다.", "흡입압력·온도를 정상기록과 비교하고 공동현상 의심 시 제작사 NPSH 자료 및 흡입조건을 검토합니다.", [211, 219]], ["토출측", 84, 66, "토출압력 · 유량", "펌프 토출측의 압력계·설치 유량계 값을 확인합니다.", "압력차 = 토출압력 − 흡입압력. 압력차만으로 전양정을 확정하지 않고 계측 높이·유속·유체조건도 고려합니다.", [211, 218]], ["모터·제어반", 50, 21, "전류 · 전압 · 주파수 · 회전수", "제어반·인버터의 표시값을 확인하고 명판·설계 운전조건과 비교합니다. 전기적 직접 측정은 담당 전문가가 시행합니다.", "전류를 허용범위와 비교합니다. 회전수·유량·양정과 부하 증가 시 가동대수를 함께 확인합니다.", [220, 224]], ["베어링·축·씰", 50, 45, "소음 · 진동 · 온도 · 누수", "접촉 없이 소음·진동·외부누수를 관찰하고 허용된 계측방법으로 온도를 확인합니다.", "기동·정지·교번운전과 진동의 관계, 베어링 마모·축정렬·씰 상태를 구분해 봅니다.", [220, 221, 222]], ["토출측 체크밸브", 68, 66, "교번운전 · 역류 징후", "현장 체크밸브의 위치와 예비펌프 계통을 도면으로 확인합니다. 그림은 단일펌프 계통의 개념 예시입니다.", "체크밸브 역류·급폐는 순환불량 또는 수충격과 연관될 수 있습니다. 교번운전 시 압력·소음을 비교합니다.", [183, 221]]], "compare": ["유량·양정·회전수를 명판과 펌프 성능곡선의 설계운전점과 비교합니다.", "주기적인 압력변동과 소음·진동은 공기·공동현상·불안정 운전을 함께 검토합니다.", "토출량이 없거나 최소유량이 부족한 경우 과열 가능성과 차압밸브 우회기능을 확인합니다."], "pro": "베어링·축정렬·씰 분해정비, 직접 전기계측과 운전범위 변경은 담당 전문가·제작사 기준에 따라 진행합니다."}, "pdcv": {"title": "차압유량조절밸브 점검 위치", "note": "P₁은 밸브 전단, P₂는 밸브 후단 공급측, P₃는 회수측 압력입니다. 밸브 손실과 제어 대상 차압을 구분합니다.", "refs": [109, 110, 115, 119], "points": [["전단 공급압력 P₁", 13, 36, "P₁ · 공급온도", "PDCV 전단의 설치 압력계와 온도계를 확인합니다.", "밸브에서 흡수하는 교축 압력차는 P₁ − P₂입니다. 제어 대상 차압과 구분하세요.", [109]], ["후단 공급압력 P₂", 65, 36, "P₂", "PDCV 후단에서 열교환설비로 공급되는 배관의 압력계를 확인합니다.", "제어 대상 공급·회수 차압은 P₂ − P₃입니다. 현장 설계차압과 비교합니다.", [109, 110]], ["회수압력 P₃", 65, 79, "P₃", "열교환설비 이후 지역난방 회수배관의 설치 압력계를 확인합니다.", "P₂와 같은 시간에 기록합니다. 사용량 변화에 따라 차압·밸브 동작이 어떻게 변하는지 확인합니다.", [109]], ["도압관·다이아프램", 42, 15, "도압관 상태 · 계측 표면온도", "공급·회수측 압력전달 도압관의 밸브·누수·막힘 가능성을 확인합니다. 고온 동관은 손으로 만지지 않고 허용된 방식으로 계측합니다.", "동관 온도와 장시간 100% 개방 등은 파손 의심 단서입니다. 온도 하나만으로 고장을 확정하지 않습니다.", [115, 118, 119]], ["스템·패킹·스프링", 42, 36, "개방 정도 · 누수 · 부식", "외부에서 밸브 개방 상태와 패킹 누수, 스프링·몸체 부식 및 동작 시 충격음을 관찰합니다.", "열사용량이 변해도 밸브가 일정 궤도에 멈추면 도압관·스템·다이아프램을 함께 검토합니다.", [115, 116, 119]]], "compare": ["제어 대상 차압: P₂ − P₃. 밸브 전후 교축 압력차: P₁ − P₂.", "109쪽의 P₁ 10.0 bar, P₂ 8.2 bar, P₃ 7.5 bar는 동작 설명용 예시값입니다. 현장 설정값으로 복사하지 않습니다.", "온도저하·밸브 개도·소음·도압관 상태를 함께 기록하고 제작사 조정방법과 설계차압을 확인합니다."], "pro": "강제동작 점검은 고온 중온수 배출을 수반하는 전문가 시행 항목입니다. 도압관 분해청소·다이아프램 교체·압력조정은 현장 절차와 제작사 기준에 따릅니다."}};

let measureKey='he',measurePoint=0;
function measurementEntry(key){return `<div class="measurement-entry"><div><h3>그림으로 점검 위치 확인</h3><p>측정 위치·기록할 값·비교 방법을 확인하세요.</p></div><button data-measure="${key}">점검 위치도 열기</button></div>`;}
function resultMeasurementLinks(w){const keys=w.id===4?['pump']:w.id===5?['he','pdcv']:w.id===6?['pdcv','pump']:w.id===7||w.id===3?['he']:['he','pump','pdcv'];return '<div class="result-measure-links"><strong>측정할 위치 확인</strong><div>'+keys.map(k=>`<button data-measure="${k}">${MEASUREMENTS[k].title}</button>`).join('')+'</div></div>';}
function diagramSVG(key){const defs='<defs><marker id="flowTip" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#517b92"/></marker></defs>';let shapes='';
if(key==='he')shapes='<rect x="235" y="68" width="170" height="245" rx="8" fill="#ecf2f5" stroke="#597a8e" stroke-width="3"/><path d="M40 104H600 M600 292H40" stroke="#547d91" stroke-width="7" fill="none"/><path d="M270 85V290 M295 85V290 M320 85V290 M345 85V290 M370 85V290" stroke="#b0c5d0" stroke-width="3"/><path d="M178 94L198 114V94L178 114Z" fill="white" stroke="#517b92" stroke-width="2"/><rect x="255" y="168" width="130" height="47" rx="5" fill="white"/><text x="320" y="198" text-anchor="middle">열교환기</text><path d="M130 104H165 M505 104H540 M505 292H470 M130 292H95" stroke="#517b92" stroke-width="3" marker-end="url(#flowTip)"/><text x="320" y="42" text-anchor="middle">1차측 · 중온수</text><text x="320" y="353" text-anchor="middle">2차측 · 난방·급탕수</text>';
if(key==='pump')shapes='<path d="M35 264H605" stroke="#547d91" stroke-width="8"/><rect x="258" y="55" width="124" height="105" rx="8" fill="#e4eef3" stroke="#597a8e" stroke-width="3"/><path d="M320 160V220" stroke="#597a8e" stroke-width="14"/><circle cx="320" cy="264" r="52" fill="#e4eef3" stroke="#597a8e" stroke-width="3"/><path d="M301 244L345 264L301 284Z" fill="#759bac"/><text x="320" y="40" text-anchor="middle">모터·제어반</text><text x="320" y="350" text-anchor="middle">순환펌프</text><text x="88" y="332" text-anchor="middle">흡입</text><text x="551" y="332" text-anchor="middle">토출</text><path d="M132 264H180 M473 264H510" stroke="#517b92" stroke-width="3" marker-end="url(#flowTip)"/>';
if(key==='pdcv')shapes='<path d="M35 144H555V316H35" stroke="#547d91" stroke-width="7" fill="none"/><rect x="500" y="192" width="100" height="75" rx="6" fill="#e4eef3" stroke="#597a8e" stroke-width="3"/><text x="550" y="223" text-anchor="middle" font-size="16">열교환</text><text x="550" y="247" text-anchor="middle" font-size="16">설비</text><rect x="226" y="116" width="85" height="55" rx="6" fill="#ddeaf0" stroke="#597a8e" stroke-width="3"/><rect x="226" y="46" width="85" height="48" rx="12" fill="#e7eff4" stroke="#597a8e" stroke-width="3"/><path d="M269 94V116 M410 144V34H305 M410 316V89H311" stroke="#849cac" stroke-width="3" fill="none" stroke-dasharray="7 5"/><text x="270" y="210" text-anchor="middle">PDCV</text><text x="74" y="195">공급</text><text x="74" y="362">회수</text><path d="M136 144H178 M455 144H485 M455 316H423" stroke="#517b92" stroke-width="3" marker-end="url(#flowTip)"/>';
return `<svg viewBox="0 0 640 400" role="img" aria-label="${MEASUREMENTS[key].title} 개념도" xmlns="http://www.w3.org/2000/svg">${defs}${shapes}</svg>`;}
function openMeasurement(key){measureKey=key;measurePoint=0;renderMeasurement();if(!$('measureDialog').open)$('measureDialog').showModal();}
function renderMeasurement(){const d=MEASUREMENTS[measureKey],p=d.points[measurePoint];$('measureTitle').textContent=d.title;$('measureContent').innerHTML=`<div class="measure-tabs">${Object.entries(MEASUREMENTS).map(([k,v])=>`<button data-measure-tab="${k}" aria-pressed="${k===measureKey}">${v.title.replace(' 점검 위치','')}</button>`).join('')}</div><p class="measure-note">${d.note}</p><p class="article-note">현장 도면과 배관 표기로 실제 위치를 대조하세요. 개념도는 설치위치·배관방향·기종을 단순화했습니다.</p><div class="measure-layout"><div><div class="equipment-diagram">${diagramSVG(measureKey)}${d.points.map((r,i)=>`<button class="point-button ${i===measurePoint?'selected':''}" style="left:${r[1]}%;top:${r[2]}%" data-point="${i}" aria-label="${i+1}번 ${r[0]}" aria-pressed="${i===measurePoint}">${i+1}</button>`).join('')}</div><div class="point-legend">${d.points.map((r,i)=>`<button data-point="${i}" class="${i===measurePoint?'selected':''}"><b>${i+1}</b> ${r[0]}</button>`).join('')}</div></div><div class="measure-detail" aria-live="polite"><span class="eyebrow">${measurePoint+1}번 위치</span><h3>${p[0]}</h3><span class="value-type">운전 중 관찰·설치 계기 확인</span><h4>기록할 값</h4><p class="record-values">${p[3]}</p><h4>어디서 확인하나요?</h4><p>${p[4]}</p><h4>어떻게 비교하나요?</h4><p>${p[5]}</p>${articleRefs(p[6])}</div></div><section class="measurement-compare"><h3>함께 비교할 항목</h3><ul>${d.compare.map(t=>`<li>${t}</li>`).join('')}</ul>${articleRefs(d.refs)}</section><div class="pro-box"><h3>전문 점검·조치</h3><p>${d.pro}</p></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.measure)openMeasurement(b.dataset.measure);else if(b.dataset.measureTab){measureKey=b.dataset.measureTab;measurePoint=0;renderMeasurement();}else if(b.hasAttribute('data-point')){measurePoint=Number(b.dataset.point);renderMeasurement();$('measureContent').querySelector('.point-button.selected')?.focus?.();}else if(b.hasAttribute('data-close-measure'))$('measureDialog').close();});
home();
